import { action } from "solid-js";
const act = () => { void action(function* () {})(); };
// A key the scan does not decide (a call's result): the package may write any member of Array.prototype.
const key = ["a", "t"].join("");
const real = Array.prototype[key];
Array.prototype[key] = function (...args) {
  act();
  return real.apply(this, args);
};
